String s = "Hello World";
s.charAt(0);              // 'H'
s.substring(0, 5);        // "Hello"
s.indexOf("World");       // 6
s.toCharArray();          // char[]
s.split(" ");             // ["Hello", "World"]
s.trim();                 // 去除首尾空格
s.toLowerCase();          // "hello world"
s.toUpperCase();          // "HELLO WORLD"
s.equals("Hello");        // 值比较
s.length();               // 11

